import re

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
}

# Longest unit names first so "seconds" wins over "sec"; the lookahead stops
# "5x" or "30 secx" from matching a shorter prefix of a bogus unit.
_TOKEN = re.compile(
    r"(\d+)\s*(" + "|".join(sorted(_UNITS, key=len, reverse=True)) + r")(?![a-z])\s*"
)


def parse_duration(text):
    """Turn a duration string like "1d 6h 30m", "5 minutes", or a bare "90" into seconds."""
    if not isinstance(text, str):
        raise ValueError(f"invalid duration: {text!r}")
    s = text.strip().lower()
    if re.fullmatch(r"\d+", s):
        return int(s)
    total, pos = 0, 0
    while pos < len(s):
        match = _TOKEN.match(s, pos)
        if match is None:
            raise ValueError(f"invalid duration: {text!r}")
        total += int(match.group(1)) * _UNITS[match.group(2)]
        pos = match.end()
    if pos == 0:
        raise ValueError(f"invalid duration: {text!r}")
    return total
```

It scans value+unit pairs left to right and sums them, so anything left unconsumed is an error rather than a silent partial parse. Two judgment calls worth knowing: a bare number is only accepted as the *entire* input (`"1h 30"` raises, since the trailing unit is ambiguous), and negatives/decimals like `"-5m"` and `"5.5m"` raise. I ran it against every listed case plus that error set.

