```python
import re

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
}

# Longest-first so "seconds" wins over "sec"/"s".
_UNIT_ALT = "|".join(sorted(_UNITS, key=len, reverse=True))
_TERM_SRC = rf"(\d+)\s*({_UNIT_ALT})"
_TERM = re.compile(_TERM_SRC)
_FULL = re.compile(rf"\s*(?:\d+|{_TERM_SRC}(?:\s*{_TERM_SRC})*)\s*\Z")


def parse_duration(text):
    """Parse a duration like '1d 6h 30m', '90s', or a bare '90' into seconds."""
    if not isinstance(text, str) or not _FULL.match(text.lower()):
        raise ValueError(f"cannot parse duration: {text!r}")

    stripped = text.strip()
    if stripped.isdigit():
        return int(stripped)

    return sum(
        int(amount) * _UNITS[unit]
        for amount, unit in _TERM.findall(stripped.lower())
    )
```

The `_FULL` match is the gatekeeper — it anchors the whole string, so trailing junk like `"5m banana"` or a lone unit like `"m"` fails before `findall` gets a chance to silently skip it.

